// .NET C# -- AWS SDK for S3
using Amazon.S3;
using Amazon.S3.Model;

var s3 = new AmazonS3Client(Amazon.RegionEndpoint.EUWest2);

var put = new PutObjectRequest {
    BucketName = "my-pipeline-data",
    Key        = "uploads/2024/orders.csv",
    FilePath   = "C:/data/orders.csv",
    ServerSideEncryptionMethod = ServerSideEncryptionMethod.AES256
};
await s3.PutObjectAsync(put);

var req = new GetPreSignedUrlRequest {
    BucketName = "my-pipeline-data", Key = "reports/q4.pdf",
    Expires = DateTime.UtcNow.AddHours(1)
};
string url = s3.GetPreSignedURL(req);

var list = await s3.ListObjectsV2Async(new ListObjectsV2Request {
    BucketName = "my-pipeline-data", Prefix = "processed/2024/"
});
foreach (var obj in list.S3Objects)
    Console.WriteLine($"{obj.Key} ({obj.Size:N0} bytes)");
